  mod.content.text:override("_PewterGymGuideAdviceText", "¡El primer POKéMON\nque sale en una partida es\ven la parte superior de la LISTA DE POKéMON\v!\f¡Al cambiar el orden\nde POKéMON, las partidas\vpodrían\vhacerse más fáciles!")
  mod.content.text:override("_PewterGymGuideBeginAdviceText", "¡Está bien! ¡Hagamos que\nsuceda!")
