  mod.content.text:override("_SSAnne2FRoomsBeautyText", "¡He oído que mucha gente\nse marea!")
  mod.content.text:override("_SSAnne2FRoomsBrunetteGirlText", "¡El CAPITÁN parecía\nrealmente enfermo y\vpálido!")
