  mod.content.text:override("_SSAnne2FRoomsGentleman1EndBattleText", "¡Buena pelea\n! ¡Ah, me siento\vjoven otra vez!")
  mod.content.text:override("_SSAnne2FRoomsGentleman2AfterBattleText", "Prefiero\nfuertes y POKéMON raros.")
  mod.content.text:override("_SSAnne2FRoomsGentleman2BattleText", "¿Cuál te gusta,\nun POKéMON fuerte o\vraro?")
