  mod.content.text:override("_SaffronCityTrainerTips1Text", "CONSEJOS DEL ENTRENADOR\fFULL HEAL cura\ntodas las dolencias como\vsueño y quemaduras.\fCuesta un poco\nmás, pero es\vmás conveniente.")
