  mod.content.text:override("_ViridianGymGiovanniPostBattleAdviceText", "¡Habiendo perdido, yo\nno puedo enfrentar a mis subordinados\v! ¡\vTEAM ROCKET está\vterminado para siempre!\f¡Dedicaré mi vida\nal estudio\vde POKéMON!\f¡Volvamos a encontrarnos\nalgún día!\v¡Adiós!")
  mod.content.text:override("_ViridianGymGiovanniPreBattleText", "¡Fwahahaha! ¡Este es\nmi escondite!\f¡Planeé\nresucitar al EQUIPO\vROCKET aquí!\f¡Pero\nme has atrapado otra vez!\v¡Que así sea! ¡Esta vez\v, no me voy a contener\v!\f¡Una vez más,\nte enfrentarás a\vGIOVANNI, el mejor entrenador de\v!")
  mod.content.text:override("_ViridianGymGiovanniReceivedEarthBadgeText", "¡Ja!\n¡Esa fue una pelea verdaderamente\vintensa!\v¡Has ganado!\vComo prueba, ¡aquí está\vel EARTHBADGE!")
  mod.content.text:override("_ViridianGymGiovanniReceivedTM27Text", "¡{PLAYER}recibió\nTM27!")
  mod.content.text:override("_ViridianGymGiovanniTM27ExplanationText", "\fTM27 es ¡FISURA!\n¡Eliminará a\vPOKéMON con solo\vun golpe!\fLo logré cuando\ndirigía el GIMNASIO aquí,\vhace demasiado tiempo...")
